1	/**
2	 * Minimal, hand-rolled subset of the Web Audio API this package actually
3	 * calls — kept independent of lib.dom's full `AudioContext`/
4	 * `OfflineAudioContext` interfaces so tests can inject a fake without a
5	 * real browser audio device, matching the dependency-injection pattern
6	 * `packages/rendering/src/render-backend.ts` and
7	 * `packages/rendering/src/canvas2d-backend.ts` use for their own
8	 * browser-only APIs (`ICanvas2DContext`, `IGPUDevice`).
9	 *
10	 * `IAudioContext` is the common surface a real `AudioContext` and a real
11	 * `OfflineAudioContext` both structurally satisfy — this is what makes
12	 * "preview and export use the exact same processing graph" achievable
13	 * (`docs/10-audio-engine/overview.md`): every function in this package
14	 * that builds a graph takes an `IAudioContext`, never the concrete
15	 * browser type, so `audio-graph.ts`/`mixer.ts`/`effects.ts` run unmodified
16	 * against either.
17	 */
18	export interface IAudioParam {
19	  value: number;
20	  setValueAtTime(value: number, startTime: number): IAudioParam;
21	  linearRampToValueAtTime(value: number, endTime: number): IAudioParam;
22	  cancelScheduledValues(startTime: number): IAudioParam;
23	}
24	
25	export interface IAudioNode {
26	  connect(destination: IAudioNode): IAudioNode;
27	  disconnect(destination?: IAudioNode): void;
28	}
29	
30	export interface IGainNode extends IAudioNode {
31	  readonly gain: IAudioParam;
32	}
33	
34	export interface IStereoPannerNode extends IAudioNode {
35	  readonly pan: IAudioParam;
36	}
37	
38	export interface IBiquadFilterNode extends IAudioNode {
39	  type: string;
40	  readonly frequency: IAudioParam;
41	  readonly Q: IAudioParam;
42	  readonly gain: IAudioParam;
43	}
44	
45	export interface IDynamicsCompressorNode extends IAudioNode {
46	  readonly threshold: IAudioParam;
47	  readonly knee: IAudioParam;
48	  readonly ratio: IAudioParam;
49	  readonly attack: IAudioParam;
50	  readonly release: IAudioParam;
51	}
52	
53	export interface IDelayNode extends IAudioNode {
54	  readonly delayTime: IAudioParam;
55	}
56	
57	export interface IConvolverNode extends IAudioNode {
58	  buffer: IAudioBuffer | null;
59	  normalize: boolean;
60	}
61	
62	/** Decoded PCM data. Matches the fields this package's DSP actually reads off a real `AudioBuffer`. */
63	export interface IAudioBuffer {
64	  readonly duration: number;
65	  readonly numberOfChannels: number;
66	  readonly sampleRate: number;
67	}
68	
69	export interface IAudioBufferSourceNode extends IAudioNode {
70	  buffer: IAudioBuffer | null;
71	  loop: boolean;
72	  readonly playbackRate: IAudioParam;
73	  onended: (() => void) | null;
74	  start(when?: number, offset?: number, duration?: number): void;
75	  stop(when?: number): void;
76	}
77	
78	export type IAudioDestinationNode = IAudioNode;
79	
80	export interface IAudioContext {
81	  readonly currentTime: number;
82	  readonly sampleRate: number;
83	  readonly destination: IAudioDestinationNode;
84	  createGain(): IGainNode;
85	  createStereoPanner(): IStereoPannerNode;
86	  createBiquadFilter(): IBiquadFilterNode;
87	  createDynamicsCompressor(): IDynamicsCompressorNode;
88	  createDelay(maxDelayTime?: number): IDelayNode;
89	  createConvolver(): IConvolverNode;
90	  createBufferSource(): IAudioBufferSourceNode;
91	}
92	
93	/**
94	 * Export render path (9.2, `docs/10-audio-engine/overview.md`
95	 * "Preview vs. export"). `OfflineAudioContext` renders as fast as
96	 * possible rather than in realtime — the graph-construction code is
97	 * identical, only `startRendering()` and the resulting buffer differ.
98	 */
99	export interface IOfflineAudioContext extends IAudioContext {
100	  startRendering(): Promise<IAudioBuffer>;
101	}
102	
103	export interface IAudioWorkletParameterMap {
104	  get(name: string): IAudioParam | undefined;
105	}
106	
107	export interface IAudioWorkletNode extends IAudioNode {
108	  readonly parameters: IAudioWorkletParameterMap;
109	}
110	
111	export interface IAudioWorkletNodeOptions {
112	  readonly processorOptions?: Record<string, unknown>;
113	}
114	
115	/**
116	 * The subset of `AudioContext`/`OfflineAudioContext` needed to register
117	 * and instantiate an `AudioWorkletNode` — split out from `IAudioContext`
118	 * because most graph code (`audio-graph.ts`, `mixer.ts`, native nodes in
119	 * `effects.ts`) never touches AudioWorklet at all.
120	 */
121	export interface IAudioWorkletContext extends IAudioContext {
122	  readonly audioWorklet: { addModule(moduleUrl: string): Promise<void> };
123	  createAudioWorkletNode(
124	    processorName: string,
125	    options?: IAudioWorkletNodeOptions,
126	  ): IAudioWorkletNode;
127	}
