1	import type { IEngine, IFrameState, LayerId } from "@motion-studio/shared";
2	import type { IRenderBackend, IRenderTargetSize } from "./render-backend";
3	import { buildSceneGraph, SceneGraphDirtyTracker, type ISceneGraph } from "./scene-graph";
4	
5	/**
6	 * Owns "Frame State → (ephemeral, per-frame) Scene Graph → Render Graph →
7	 * GPU backend → Canvas" (CLAUDE.md engine ownership table). Never imports
8	 * Timeline/Animation/Layer/Storage internals — it only ever receives a
9	 * Frame State and produces pixels through the injected `IRenderBackend`
10	 * (ADR-004: the one GPU abstraction). Which concrete backend to construct
11	 * (WebGPU/WebGL2/Canvas2D/Software) is a host-app decision — see
12	 * `backend-detection.ts`'s `selectBackend` — because only the host has the
13	 * real `<canvas>`/GPU device to hand the backend its dependencies.
14	 */
15	export class RenderingEngine implements IEngine {
16	  readonly name = "Rendering";
17	
18	  private readonly backend: IRenderBackend;
19	  private readonly dirtyTracker = new SceneGraphDirtyTracker();
20	
21	  constructor(backend: IRenderBackend) {
22	    this.backend = backend;
23	  }
24	
25	  initialize(): void {}
26	
27	  ready(): void {}
28	
29	  async dispose(): Promise<void> {
30	    await this.backend.dispose();
31	  }
32	
33	  async setTarget(size: IRenderTargetSize): Promise<void> {
34	    await this.backend.init(size);
35	  }
36	
37	  /** Builds the Scene Graph for `frameState`, updates dirty-tracking, and draws it. Returns the built Scene Graph for inspection/testing. */
38	  async renderFrame(frameState: IFrameState): Promise<ISceneGraph> {
39	    const sceneGraph = buildSceneGraph(frameState);
40	    this.dirtyTracker.update(sceneGraph);
41	    await this.backend.drawFrame(sceneGraph);
42	    return sceneGraph;
43	  }
44	
45	  isDirty(layerId: LayerId): boolean {
46	    return this.dirtyTracker.graph.isDirty(layerId);
47	  }
48	}
49

