1	import type { AppEvent, AppEventMap, AppEventType } from "@motion-studio/shared";
2	
3	export type EventListener<T extends AppEventType> = (event: AppEvent<T>) => void;
4	export type AsyncEventListener<T extends AppEventType> = (
5	  event: AppEvent<T>,
6	) => void | Promise<void>;
7	
8	/**
9	 * Typed publish/subscribe bus for coarse notifications (selection changed,
10	 * export finished, etc). Not the per-frame hot path — see Scheduler for
11	 * that direct call chain. Every listener declares its exact event type;
12	 * there is no wildcard subscription mechanism. See
13	 * docs/04-core/core-overview.md and CLAUDE.md "Canonical names".
14	 */
15	export class EventBus {
16	  private readonly listeners = new Map<AppEventType, Set<AsyncEventListener<AppEventType>>>();
17	
18	  on<T extends AppEventType>(
19	    type: T,
20	    listener: EventListener<T> | AsyncEventListener<T>,
21	  ): () => void {
22	    let set = this.listeners.get(type);
23	    if (!set) {
24	      set = new Set();
25	      this.listeners.set(type, set);
26	    }
27	    set.add(listener as AsyncEventListener<AppEventType>);
28	    return () => this.off(type, listener);
29	  }
30	
31	  off<T extends AppEventType>(type: T, listener: EventListener<T> | AsyncEventListener<T>): void {
32	    this.listeners.get(type)?.delete(listener as AsyncEventListener<AppEventType>);
33	  }
34	
35	  /** Synchronous dispatch. Async listeners run, but their promises are not awaited. */
36	  emit<T extends AppEventType>(type: T, payload: AppEventMap[T]): void {
37	    const event = { type, payload, timestamp: Date.now() } as AppEvent<T>;
38	    for (const listener of this.listenersFor(type)) {
39	      try {
40	        void listener(event);
41	      } catch (error) {
42	        this.reportListenerError(type, error);
43	      }
44	    }
45	  }
46	
47	  /** Dispatch and await every listener, so callers can wait for async side effects. */
48	  async emitAsync<T extends AppEventType>(type: T, payload: AppEventMap[T]): Promise<void> {
49	    const event = { type, payload, timestamp: Date.now() } as AppEvent<T>;
50	    const results = await Promise.allSettled(
51	      this.listenersFor(type).map((listener) => listener(event)),
52	    );
53	    for (const result of results) {
54	      if (result.status === "rejected") {
55	        this.reportListenerError(type, result.reason);
56	      }
57	    }
58	  }
59	
60	  private listenersFor<T extends AppEventType>(type: T): AsyncEventListener<T>[] {
61	    const set = this.listeners.get(type);
62	    return set ? (Array.from(set) as AsyncEventListener<T>[]) : [];
63	  }
64	
65	  private reportListenerError(type: AppEventType, error: unknown): void {
66	    // A single failing listener must not break the bus or other listeners.
67	    // Centralized error reporting policy is an open item in
68	    // docs/04-core/core-overview.md; console.error is the placeholder sink.
69	    console.error(`[EventBus] listener for "${type}" threw:`, error);
70	  }
71	}
72

